#!/usr/bin/env bun

// Mirrors the Claude Code configuration (~/.claude) into the Antigravity CLI configuration (~/.gemini).
// Re-runnable: files generated by a previous run are removed first.
// Usage: bun run antigravity-sync (from ~/.claude/scripts)

import { removePreviouslyGeneratedPaths, saveGeneratedPaths } from "./lib/generated_manifest";
import { syncAgentMap } from "./lib/sync_agent_map";
import { syncAgents } from "./lib/sync_agents";
import { syncHooks } from "./lib/sync_hooks";
import { syncMcpServers } from "./lib/sync_mcp_servers";
import { syncPermissions } from "./lib/sync_permissions";
import { syncGlobalRules } from "./lib/sync_rules";
import { syncSkills } from "./lib/sync_skills";

const SYNC_STEPS = [syncGlobalRules, syncSkills, syncAgents, syncAgentMap, syncMcpServers, syncHooks, syncPermissions];

function main() {
	try {
		const removedCount = removePreviouslyGeneratedPaths();
		console.log(`cleanup: ${removedCount} previously generated paths removed`);
		const generatedPaths = SYNC_STEPS.flatMap((syncStep) => syncStep());
		saveGeneratedPaths(generatedPaths);
		console.log("done. Restart agy to load the new configuration.");
	} catch (error) {
		console.error(`sync failed: ${(error as Error).message}`);
		process.exit(1);
	}
}

main();
